/**
 * @param {number[]} nums
 * @return {number}
 */
var smallestUniqueSubarray = function(nums) {
    const n = nums.length;

    for (let k = 1; k <= n; k++) {
        let cur = nums.slice(0, k).join(',');

        const map = new Map([[cur, 1]]);
        let unique = 1;

        for (let i = k; i < n; i++) {
            cur = cur.slice(nums[i - 1].toString().length);
            if (cur.length > 0 && cur[0] === ',') cur = cur.slice(1);
            if (cur.length > 0) cur += ',';
            cur += nums[i];

            const count = map.get(cur) || 0;
            if (count === 0) unique++;
            if (count === 1) unique--;
            map.set(cur, count + 1);
        }

        if (unique > 0) return k;
    }

    return n;
};

